const decoded = Buffer.from($('Get careers-page.json').first().json.content, 'base64').toString('utf-8');
const page = JSON.parse(decoded);
const agentRaw = $('Create agent').first().json.text;
const agentParsed = JSON.parse(agentRaw);
const agentOutput = agentParsed.output;
const requirements = $('Get Requirements Agent').first().json.output.requirements;
const position = (requirements.page_position || '').toLowerCase();
const blockId = "custom-" + Date.now();
const filePath = "blocks/" + blockId + ".html";
const newBlock = {
  id: blockId,
  type: "custom-code",
  config: { src: filePath, name: agentOutput.name }
};
let insertIndex = page.blocks.length;
if (position.includes('hero')) {
  const i = page.blocks.findIndex(b => b.type === 'hero');
  if (i !== -1) insertIndex = i + 1;
} else if (position.includes('job')) {
  const i = page.blocks.findIndex(b => b.type === 'job-list');
  if (i !== -1) insertIndex = i + 1;
}
page.blocks.splice(insertIndex, 0, newBlock);
const updated = JSON.stringify(page, null, 2);
return [{
  json: {
    newContent: updated,
    newContentBase64: Buffer.from(updated, 'utf-8').toString('base64'),
    jsonSha: $('Get careers-page.json').first().json.sha,
    htmlPath: filePath,
    htmlBase64: Buffer.from(agentOutput.snippet, 'utf-8').toString('base64'),
    blockName: agentOutput.name,
    how: agentOutput.how
  }
}];

