const raw = $('Get careers-page.json').item.json.content;
const decoded = Buffer.from(raw, 'base64').toString('utf-8');
const page = JSON.parse(decoded);
const agentRaw = $('Event-tracking agent').item.json.text;
const agentParsed = JSON.parse(agentRaw);
const agentOutput = agentParsed.output;
const blockId = "custom-" + Date.now();
const filePath = "blocks/" + blockId + ".html";
const newBlock = {
  id: blockId,
  type: "custom-code",
  config: {
    src: "blocks/" + blockId + ".html",
    name: agentOutput.name,
    placement: "head"
  }
};
// Pixels go at the top of the page (head injection)
page.blocks.unshift(newBlock);
const updated = JSON.stringify(page, null, 2);
return [{
  json: {
    newContent: updated,
    newContentBase64: Buffer.from(updated, 'utf-8').toString('base64'),
    sha: $('Get careers-page.json').item.json.sha,
    htmlPath: filePath,
    htmlBase64: Buffer.from(agentOutput.snippet, 'utf-8').toString('base64'),
    blockName: agentOutput.name
  }
}];

